import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";
import { useNavigate } from "react-router-dom";

export default function Match({ userEmail, onGameStart }) {
  const [entryFee, setEntryFee] = useState(13);
  const [status, setStatus] = useState("");
  const [game, setGame] = useState(null);
  const [playerId, setPlayerId] = useState(null);
  const [loading, setLoading] = useState(false);
  const [gameStarted, setGameStarted] = useState(false);

  const stompClientRef = useRef(null);
  const pollingRef = useRef(null);
  const timeoutRef = useRef(null);

  const navigate = useNavigate();
  const ALLOWED_FEES = [13, 23, 50];

  useEffect(() => {
    const checkExistingMatch = async () => {
      const token = localStorage.getItem("authToken");
      try {
        const res = await axios.get("http://localhost:8080/api/match/status", {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        if (res.data?.id) {
          setGame(res.data);
          setStatus("⚠️ আগের একটি ম্যাচ পাওয়া গেছে, যুক্ত হচ্ছি...");
        }
      } catch (err) {
        console.warn("❗ আগের ম্যাচ চেক করতে সমস্যা হয়েছে।");
      }
    };

    checkExistingMatch();
  }, []);

  useEffect(() => {
    if (!game?.id || gameStarted) return;

    const token = localStorage.getItem("authToken");
    const socket = new SockJS(`http://localhost:8080/ludo-ws?token=${token}`);
    const client = new Client({
      webSocketFactory: () => socket,
      debug: (str) => console.log("🔧", str),
      onConnect: () => {
        console.log("🟢 WebSocket connected");

        client.subscribe(`/topic/match/${game.id}`, (message) => {
          const gameSession = JSON.parse(message.body);
          console.log("📩 ম্যাচ আপডেট:", gameSession);

          setGame(gameSession);

          const { player1, player2 } = gameSession;

          if (player1?.id && player2?.id && !gameStarted) {
            const isPlayer1 = userEmail === player1.email;
            const isPlayer2 = userEmail === player2.email;

            if (isPlayer1 || isPlayer2) {
              const playerNumber = isPlayer1 ? 1 : 2;
              setPlayerId(playerNumber);
              setStatus("🎮 Game started! Redirecting...");
              setGameStarted(true);

              // ✅ Store to localStorage
              localStorage.setItem("gameId", gameSession.id);
              localStorage.setItem("playerId", playerNumber);
              localStorage.setItem("entryFee", entryFee);

              onGameStart({
                gameId: gameSession.id,
                playerId: playerNumber,
                entryFee,
              });

              clearInterval(pollingRef.current);
              clearTimeout(timeoutRef.current);

              setTimeout(() => {
                navigate("/game");
              }, 1000);
            } else {
              setStatus("⚠️ You are not a participant of this game.");
            }
          } else {
            setStatus("🎉 Opponent পাওয়া গেছে, অপেক্ষা করছি...");
          }
        });
      },
      onStompError: (frame) => {
        console.error("❌ STOMP Error:", frame);
        setStatus("❌ WebSocket error হয়েছে!");
      },
    });

    client.activate();
    stompClientRef.current = client;

    return () => {
      client.deactivate();
      clearInterval(pollingRef.current);
      clearTimeout(timeoutRef.current);
    };
  }, [game?.id, gameStarted, userEmail, entryFee, onGameStart]);

  const handleMatchRequest = async () => {
    if (!ALLOWED_FEES.includes(entryFee)) {
      setStatus("❌ Invalid fee. 13, 23, 50 সিলেক্ট করো।");
      return;
    }

    setLoading(true);
    setStatus("🔍 Opponent খুঁজছি...");

    const token = localStorage.getItem("authToken");

    try {
      await axios.post(
        "http://localhost:8080/api/match/start",
        { entryFee },
        {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }
      );

      pollingRef.current = setInterval(async () => {
        try {
          const statusRes = await axios.get(
            "http://localhost:8080/api/match/status",
            {
              headers: {
                Authorization: `Bearer ${token}`,
              },
            }
          );
          const gameData = statusRes.data;

          if (gameData?.id) {
            clearInterval(pollingRef.current);
            clearTimeout(timeoutRef.current);
            setGame(gameData);
            setStatus("🎉 Opponent পাওয়া গেছে!");
          }
        } catch (err) {
          console.error("Polling error", err);
        }
      }, 3000);

      timeoutRef.current = setTimeout(() => {
        clearInterval(pollingRef.current);
        setStatus("⏳ ৩০ মিনিটে Opponent পাওয়া যায়নি, আবার চেষ্টা করুন।");
        setLoading(false);
        if (stompClientRef.current) {
          stompClientRef.current.deactivate();
        }
      }, 30 * 60 * 1000);
    } catch (err) {
      if (err.response?.status === 409) {
        try {
          const res = await axios.get("http://localhost:8080/api/match/status", {
            headers: {
              Authorization: `Bearer ${token}`,
            },
          });

          if (res.data?.id) {
            setGame(res.data);
            setStatus("⚠️ আগের একটি ম্যাচে আপনি যুক্ত আছেন।");
          } else {
            setStatus("⚠️ আগের একটি ম্যাচ পাওয়া যায়নি।");
          }
        } catch (fetchError) {
          setStatus("❗ আগের ম্যাচ তথ্য আনতে সমস্যা হয়েছে।");
        }
      } else {
        console.error("❗ Server error:", err);
        setStatus("⚠️ সার্ভার সমস্যা: " + (err.response?.data || "Unknown error"));
      }
    } finally {
      setLoading(false);
    }
  };

  const handleResumeGame = () => {
    navigate("/game");
  };

  return (
    <div className="max-w-lg mx-auto mt-12 p-6 bg-white border rounded-xl shadow-lg">
      <h2 className="text-2xl font-bold text-center text-indigo-700 mb-6">
        🎲 Start a Ludo Match
      </h2>

      <div className="mb-5">
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Select Entry Fee
        </label>
        <select
          value={entryFee}
          onChange={(e) => setEntryFee(Number(e.target.value))}
          className="w-full px-4 py-2 border rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
        >
          {ALLOWED_FEES.map((fee) => (
            <option key={fee} value={fee}>
              ৳ {fee}
            </option>
          ))}
        </select>
      </div>

      <button
        onClick={handleMatchRequest}
        disabled={loading}
        className={`w-full py-2 px-4 text-white font-semibold rounded-md shadow-md transition ${
          loading
            ? "bg-gray-400 cursor-not-allowed"
            : "bg-indigo-600 hover:bg-indigo-700"
        }`}
      >
        {loading ? "⏳ Finding..." : "🔍 Find Opponent"}
      </button>

      {status && (
        <div className="mt-6 text-sm text-center text-gray-700">
          <strong>Status:</strong> {status}
        </div>
      )}

      {game?.id && !gameStarted && (
        <div className="mt-6 p-4 text-center border border-green-400 bg-green-50 rounded-md">
          <p className="text-green-700 font-bold">✅ Game ID: {game.id}</p>
          <p className="text-green-600">👤 You are Player {playerId}</p>

          <button
            onClick={handleResumeGame}
            className="mt-4 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition"
          >
            🔁 আগের গেমে ফিরে যান
          </button>
        </div>
      )}
    </div>
  );
}
